<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; $edit = isset($_GET['edit']) ? App\Db::one('SELECT * FROM workflows WHERE slug = ?', [$_GET['edit']]) : null; ?>
<div class="topbar"><div><h1>Workflows</h1><p class="muted" style="margin:4px 0 0">Event-triggered automations. Runs are durable: they survive delays, approvals and server restarts.</p></div></div>
<div class="grid g2" style="align-items:start"><div class="panel"><h2>Definitions</h2><?php foreach ($rows as $w): ?><div class="row spread" style="padding:8px 0;border-bottom:1px solid var(--line-2)"><div><b><?= e($w['name']) ?></b><div class="small muted">on <span class="kbd"><?= e($w['trigger_event']) ?></span> · v<?= (int)$w['version'] ?> · <?= count(jdec($w['definition'])['steps'] ?? []) ?> steps</div></div><div class="row"><?php $badge($w['enabled'] ? 'enabled' : 'disabled'); ?><a class="btn btn-ghost btn-sm" href="?edit=<?= e($w['slug']) ?>">Edit</a></div></div><?php endforeach; ?>
  <a class="btn btn-ghost btn-sm" style="margin-top:12px" href="?edit=new">New workflow</a></div>
<?php if ($edit || ($_GET['edit'] ?? '') === 'new'): ?><form class="panel" method="post" action="/admin/workflows"><?= App\Csrf::field() ?><h2><?= $edit ? 'Edit ' . e($edit['name']) : 'New workflow' ?></h2>
  <div class="grid g2"><div class="field"><label for="sl">Slug</label><input id="sl" name="slug" type="text" value="<?= e($edit['slug'] ?? '') ?>" <?= $edit ? 'readonly' : 'required' ?>></div><div class="field"><label for="nm">Name</label><input id="nm" name="name" type="text" value="<?= e($edit['name'] ?? '') ?>" required></div></div>
  <div class="field"><label for="tr">Trigger event</label><input id="tr" name="trigger_event" type="text" value="<?= e($edit['trigger_event'] ?? '') ?>" placeholder="lead.created · order.paid · project.completed · ticket.created · proposal.sent · payment.failed · task.completed" required></div>
  <div class="field"><label for="df">Steps (JSON)</label><textarea id="df" name="definition" style="font-family:var(--mono);font-size:.8rem;min-height:260px"><?= e(json_encode(jdec($edit['definition'] ?? '{"steps":[]}'), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></textarea>
    <div class="hint">Step types: action · agent_task {agent, kind, title, brief} · condition {field, op: eq|neq|gte|lte|truthy, value, else: stop|continue} · delay {seconds} · approval {title, what} · notify {template, to: customer|owner, dedupe} · webhook {url (public https)}. Templates: <?= e(implode(', ', $templates)) ?></div></div>
  <label class="check"><input type="checkbox" name="enabled" value="1"<?= ($edit['enabled'] ?? 1) ? ' checked' : '' ?>> Enabled</label><button class="btn btn-primary" style="margin-top:10px">Validate &amp; save</button></form><?php endif; ?></div>
<div class="panel"><h2>Recent runs</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Workflow</th><th>Status</th><th>Step</th><th>Last log</th><th>Updated</th><th></th></tr></thead><tbody>
<?php foreach ($runs as $r): $log = jdec($r['log']); $last = end($log) ?: []; ?><tr><td><?= (int)$r['id'] ?></td><td><?= e($r['workflow_slug']) ?></td><td><?php $badge($r['status']); ?></td><td><?= (int)$r['current_step'] ?></td><td class="small"><?= e(($last['type'] ?? '') . ' ' . ($last['result'] ?? '')) ?><?= $r['error'] ? '<div style="color:var(--red)">' . e(str_limit($r['error'], 120)) . '</div>' : '' ?></td><td class="small"><?= e(substr($r['updated_at'], 0, 16)) ?></td>
  <td><?php if ($r['status'] === 'failed'): ?><form method="post" action="/admin/workflows/run/<?= (int)$r['id'] ?>"><?= App\Csrf::field() ?><button class="btn btn-ghost btn-sm">Retry</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
